import argparse, hashlib, http.server, json, os, pathlib, socket, subprocess, threading, time, urllib.request, uuid

parser = argparse.ArgumentParser()
parser.add_argument('--magpie', required=True, help='Path to the Windows magpie.exe under test')
args = parser.parse_args()
