env = os.environ.copy()
env.update({'XDG_CONFIG_HOME': str(WORK / 'config'), 'XDG_CACHE_HOME': str(WORK / 'cache'), 'MAGPIE_ADDR': '127.0.0.1:' + str(port), 'MAGPIE_WEB_KEY': uuid.uuid4().hex})
